const os=require('node:os'),privateFiles={"server_asks/create_asks.js":"function create_asks(resources) {\n    const { all, audit, get, run, tx, V2Error, badRequest, conflict, forbidden, notFound, event, newId, nowIso, sha256hex, take, cleanProse, isBlankText, goalObj, goalRow, canReadGoal, memberName, need, readDate } = resources;\n    const ASK_STATES = [\"open\", \"accepted\", \"done\", \"declined\", \"withdrawn\"];\n    const ASK_ACTIONS = [\"accept\", \"decline\", \"done\", \"reopen\", \"withdraw\", \"mention\"];\n    /** Caps (docs/v2/WIRE.md \"Asks\"). */\n    const ASK_TEXT_MAX = 400;\n    const ASK_FROM_MAX = 80;\n    const ASK_TITLE_MAX = 120;\n    const MENTION_TEXT_MAX = 300;\n    const MENTIONS_MAX = 10;\n    const IMPORT_MAX = 60;\n    /** Open and accepted asks per workspace. */\n    const OPEN_ASKS_MAX = 500;\n    /** Asks created (recorded or imported) per workspace per hour. */\n    const ASKS_PER_HOUR = 60;\n    /** Ask actions per person per minute. */\n    const ASK_ACTIONS_PER_MINUTE = 30;\n    // ---- input ----\n    /** People's text: control characters become spaces (as v1 did), invisible characters are dropped and blank fillers made\n     *  spaces (lib/v2/text-core.mts), then trimmed and bounded; nothing a person can read left is missing (W3). */\n    function text(v, field, max, { optional = false } = {}) {\n        if (v === undefined || v === null || (optional && v === \"\")) {\n            if (optional)\n                return null;\n            throw badRequest(`${field} is required`);\n        }\n        if (typeof v !== \"string\")\n            throw badRequest(`${field} must be a string`);\n        const t = cleanProse(v.replace(/[\\u0000-\\u001f\\u007f-\\u009f]/g, \" \"));\n        if (isBlankText(t)) {\n            if (optional)\n                return null;\n            throw badRequest(`${field} is required`);\n        }\n        if (t.length > max)\n            throw badRequest(`${field} is too long (max ${max} characters)`);\n        return t;\n    }\n    const DAY = /^\\d{4}-\\d{2}-\\d{2}$/;\n    function day(v, field) {\n        if (typeof v !== \"string\" || !DAY.test(v) || Number.isNaN(readDate().parse(`${v}T00:00:00Z`)) || new (readDate())(`${v}T00:00:00Z`).toISOString().slice(0, 10) !== v) {\n            throw badRequest(`${field} must be a date like 2026-10-26`);\n        }\n        return v;\n    }\n    const obj = (v, field) => {\n        if (!v || typeof v !== \"object\" || Array.isArray(v))\n            throw badRequest(`${field} must be an object`);\n        return v;\n    };\n    /** The team an ask names: `team_id`, or (an import, which people write by hand) `team`, a team's name in this\n     *  workspace, matched without regard to case (400 when no team or more than one has it). */\n    function askTeam(pp, b, prefix) {\n        if ((b.team_id === undefined || b.team_id === null) && typeof b.team === \"string\") {\n            const name = text(b.team, `${prefix}team`, 200);\n            const ids = all(\"SELECT id FROM v2_pods WHERE ws_id = ? AND lower(name) = lower(?)\", pp.wsId, name);\n            if (ids.length !== 1)\n                throw badRequest(`${prefix}team: ${ids.length ? \"more than one team\" : \"no team\"} here is called \"${name}\"`);\n            return ids[0].id;\n        }\n        if (b.team_id === undefined || b.team_id === null || b.team_id === \"\")\n            throw badRequest(`${prefix}team_id (or ${prefix}team, a team's name) is required`);\n        const teamId = text(b.team_id, `${prefix}team_id`, 64);\n        if (!get(\"SELECT 1 AS x FROM v2_pods WHERE ws_id = ? AND id = ?\", pp.wsId, teamId))\n            throw notFound();\n        return teamId;\n    }\n    /** A new ask's fields. The team must exist (404 for an unknown team_id); a goal must be readable (404) and the asked\n     *  team's own (400). */\n    function askIn(pp, b, prefix = \"\") {\n        const teamId = askTeam(pp, b, prefix);\n        const goalId = text(b.goal_id, `${prefix}goal_id`, 64, { optional: true });\n        if (goalId) {\n            const g = goalRow(pp.wsId, goalId);\n            if (!g || !canReadGoal(pp, goalObj(g)))\n                throw notFound();\n            if (g.pod_id !== teamId)\n                throw badRequest(`${prefix}goal_id must be a goal of the team asked`);\n        }\n        const s = obj(b.source, `${prefix}source`);\n        const kind = s.kind === \"meeting\" || s.kind === \"manual\" ? s.kind : null;\n        if (!kind)\n            throw badRequest(`${prefix}source.kind must be meeting or manual`);\n        const title = text(s.title, `${prefix}source.title`, ASK_TITLE_MAX, { optional: kind === \"manual\" });\n        return {\n            teamId,\n            goalId,\n            text: text(b.text, `${prefix}text`, ASK_TEXT_MAX),\n            fromLabel: text(b.from_label, `${prefix}from_label`, ASK_FROM_MAX, { optional: true }),\n            source: { kind, title, date: day(s.date, `${prefix}source.date`) },\n        };\n    }\n    const mentionIn = (b, prefix = \"\") => ({\n        date: day(b.date, `${prefix}date`),\n        text: text(b.text, `${prefix}text`, MENTION_TEXT_MAX),\n        source_title: text(b.source_title, `${prefix}source_title`, ASK_TITLE_MAX),\n    });\n    // ---- who may do what ----\n    const isOwner = (pp) => pp.wsRole === \"owner\";\n    const inTeam = (pp, a) => pp.pods.has(a.team_id);\n    const leads = (pp, a) => pp.pods.get(a.team_id) === \"lead\";\n    const writer = (pp) => pp.wsRole === \"owner\" || pp.wsRole === \"member\";\n    /** The requester, every member and lead of the asked team, and workspace owners. */\n    const canReadAsk = (pp, a) => !!pp.wsRole && (a.created_by === pp.userId || pp.pods.has(a.team_id) || pp.wsRole === \"owner\");\n    function canFlags(pp, a) {\n        if (!writer(pp))\n            return { accept: false, decline: false, done: false, reopen: false, withdraw: false, mention: false };\n        const decide = leads(pp, a) || isOwner(pp);\n        return {\n            accept: a.state === \"open\" && decide,\n            decline: a.state === \"open\" && decide,\n            done: a.state === \"accepted\" && (inTeam(pp, a) || isOwner(pp)),\n            reopen: (a.state === \"done\" || a.state === \"declined\") && decide,\n            withdraw: (a.state === \"open\" || a.state === \"accepted\") && a.created_by === pp.userId,\n            mention: a.state === \"open\" || a.state === \"accepted\",\n        };\n    }\n    /** Waiting on this reader: an open ask of a team they lead, or an accepted ask of a team they are in. A workspace owner\n     *  outside the team is waited on only when the team has nobody who could (no lead to decide; nobody to finish it). */\n    function waitingOn(pp, a, can) {\n        if (can.accept)\n            return leads(pp, a) || !get(\"SELECT 1 AS x FROM v2_pod_members WHERE ws_id = ? AND pod_id = ? AND role = 'lead'\", a.ws_id, a.team_id);\n        if (can.done)\n            return inTeam(pp, a) || !get(\"SELECT 1 AS x FROM v2_pod_members WHERE ws_id = ? AND pod_id = ?\", a.ws_id, a.team_id);\n        return false;\n    }\n    // ---- reading ----\n    const askRow = (ws, id) => get(\"SELECT * FROM v2_asks WHERE ws_id = ? AND id = ?\", ws, id);\n    function visibleAsk(pp, id) {\n        need(pp, \"workspace.read\");\n        const a = askRow(pp.wsId, id);\n        if (!a || !canReadAsk(pp, a))\n            throw notFound();\n        return a;\n    }\n    /** Names and titles looked up once per listing. */\n    function viewer(pp) {\n        const people = new Map();\n        const teams = new Map();\n        const goals = new Map();\n        const person = (id) => {\n            if (!people.has(id))\n                people.set(id, { id, name: memberName(id) });\n            return people.get(id);\n        };\n        const team = (id) => {\n            if (!teams.has(id))\n                teams.set(id, { id, name: get(\"SELECT name FROM v2_pods WHERE ws_id = ? AND id = ?\", pp.wsId, id)?.name ?? \"\" });\n            return teams.get(id);\n        };\n        const goal = (id) => {\n            if (!id)\n                return null;\n            if (!goals.has(id)) {\n                const g = goalRow(pp.wsId, id);\n                goals.set(id, g && canReadGoal(pp, goalObj(g)) ? { id: g.id, title: g.title } : null);\n            }\n            return goals.get(id);\n        };\n        return (a, mentions, via) => {\n            const can = via ? NO_ACTIONS : canFlags(pp, a);\n            return {\n                id: a.id,\n                state: a.state,\n                team: team(a.team_id),\n                goal: goal(a.goal_id),\n                text: a.text,\n                from_label: a.from_label,\n                requester: person(a.created_by),\n                source: { kind: a.source_kind, title: a.source_title, date: a.source_date },\n                mentions: mentions.map((m) => ({ n: m.n, date: m.date, text: m.text, source_title: m.source_title, added_by: person(m.added_by) })),\n                decided_by: a.decided_by ? person(a.decided_by) : null,\n                decided_at: a.decided_at,\n                created_at: a.created_at,\n                updated_at: a.updated_at,\n                waiting_on_me: via ? false : waitingOn(pp, a, can),\n                can,\n                ...(via ? { via_alignment: { goal_id: via } } : {}),\n            };\n        };\n    }\n    const NO_ACTIONS = { accept: false, decline: false, done: false, reopen: false, withdraw: false, mention: false };\n    /** The teams whose accepted asks a device also reads (A1-cross-2): for each live shared session of this person on this\n     *  device that follows a goal through an approved \"work toward\" alignment (its governing goal is that alignment's\n     *  target), the goal's team, with the goal followed. A revoked or declined alignment, a session no longer shared (or\n     *  suspended), one moved off the goal and a contribution-only alignment (which governs nothing) give nothing. */\n    function alignedTeams(pp, deviceId) {\n        const rows = all(`SELECT DISTINCT g.pod_id AS team_id, g.id AS goal_id FROM v2_sessions s\n       JOIN v2_alignments al ON al.ws_id = s.ws_id AND al.id = s.governing_alignment_id\n       JOIN v2_goals g ON g.ws_id = s.ws_id AND g.id = s.governing_goal_id\n     WHERE s.ws_id = ? AND s.user_id = ? AND s.device_id = ? AND s.state = 'shared'\n       AND al.state = 'approved' AND al.target_goal_id = s.governing_goal_id AND g.pod_id IS NOT NULL\n     ORDER BY g.id`, pp.wsId, pp.userId, deviceId);\n        const out = new Map();\n        for (const r of rows)\n            if (!out.has(r.team_id))\n                out.set(r.team_id, r.goal_id);\n        return out;\n    }\n    const mentionsOf = (askId) => all(\"SELECT * FROM v2_ask_mentions WHERE ask_id = ? ORDER BY n\", askId);\n    function getAsk(pp, id) {\n        const a = visibleAsk(pp, id);\n        return viewer(pp)(a, mentionsOf(a.id));\n    }\n    const STATE_ORDER = { open: 0, accepted: 1, done: 2, declined: 2, withdrawn: 2 };\n    /** Readable asks, filtered: the reader's own (their teams' and those they recorded) first, then open, accepted and\n     *  closed, then the newest source date, then the newest recorded; at most `limit` (default all). */\n    function listAsks(pp, o = {}) {\n        need(pp, \"workspace.read\");\n        const where = [\"ws_id = ?\"];\n        const params = [pp.wsId];\n        if (o.states?.length) {\n            where.push(`state IN (${o.states.map(() => \"?\").join(\", \")})`);\n            params.push(...o.states);\n        }\n        if (o.teamId) {\n            where.push(\"team_id = ?\");\n            params.push(o.teamId);\n        }\n        const mine = (a) => (pp.pods.has(a.team_id) || a.created_by === pp.userId ? 0 : 1);\n        // An ask read only through a followed team (device feed): accepted ones, marked with the goal followed.\n        const via = (a) => (!canReadAsk(pp, a) && a.state === \"accepted\" ? o.followed?.get(a.team_id) : undefined);\n        const rows = all(`SELECT * FROM v2_asks WHERE ${where.join(\" AND \")}`, ...params)\n            .filter((a) => canReadAsk(pp, a) || !!via(a))\n            .sort((a, b) => mine(a) - mine(b) ||\n            STATE_ORDER[a.state] - STATE_ORDER[b.state] ||\n            b.source_date.localeCompare(a.source_date) ||\n            b.created_at.localeCompare(a.created_at) ||\n            a.id.localeCompare(b.id))\n            .slice(0, o.limit ?? Infinity);\n        const byAsk = new Map();\n        if (rows.length) {\n            for (const m of all(\"SELECT * FROM v2_ask_mentions WHERE ws_id = ? ORDER BY ask_id, n\", pp.wsId)) {\n                if (!byAsk.has(m.ask_id))\n                    byAsk.set(m.ask_id, []);\n                byAsk.get(m.ask_id).push(m);\n            }\n        }\n        const view = viewer(pp);\n        return rows.map((a) => view(a, byAsk.get(a.id) ?? [], via(a)));\n    }\n    /** The asks this person can read, filtered by state and team: their own teams' (and the asks they recorded) first,\n     *  then open, accepted and closed, then the newest source date; at most `limit`. */\n    function readableAsks(pp, o = {}) {\n        return listAsks(pp, { states: o.state ? [o.state] : undefined, teamId: o.teamId, limit: o.limit });\n    }\n    /** The asks feed (GET .../asks, browser or device): readable asks, filtered, with a short version hash for ETag /\n     *  If-None-Match. `state` may list several states, comma-separated. 400 for an unknown state. A device (`deviceId`)\n     *  also gets the accepted asks of the teams its sessions follow through an approved alignment (alignedTeams). */\n    function asksFeed(pp, q, deviceId = null) {\n        const states = q.state ? q.state.split(\",\").map((s) => s.trim()) : [];\n        if (states.some((s) => !ASK_STATES.includes(s)))\n            throw badRequest(`state must be one or more of ${ASK_STATES.join(\", \")}`);\n        if (q.teamId && !/^pod_[A-Za-z0-9_-]{8,64}$/.test(q.teamId))\n            throw badRequest(\"team_id must be a team id\");\n        const limit = q.limit ? Number(q.limit) : FEED_MAX;\n        if (!Number.isSafeInteger(limit) || limit < 1 || limit > FEED_MAX)\n            throw badRequest(`limit must be 1 to ${FEED_MAX}`);\n        const followed = deviceId ? alignedTeams(pp, deviceId) : undefined;\n        const asks = listAsks(pp, { states: states, teamId: q.teamId ?? undefined, limit, followed });\n        return { version: sha256hex(JSON.stringify(asks)).slice(0, 16), asks };\n    }\n    const FEED_MAX = 500;\n    /** The open and accepted asks of the person's teams for align_get_brief: open first, then most mentions, then newest;\n     *  at most 5, and how many more there are. */\n    function asksForBrief(pp) {\n        const list = listAsks(pp, { states: [\"open\", \"accepted\"] })\n            .filter((a) => pp.pods.has(a.team.id))\n            .sort((a, b) => STATE_ORDER[a.state] - STATE_ORDER[b.state] || b.mentions.length - a.mentions.length || b.source.date.localeCompare(a.source.date) || b.created_at.localeCompare(a.created_at));\n        return { asks: list.slice(0, 5), more: Math.max(0, list.length - 5) };\n    }\n    // ---- writing ----\n    function requireWriter(pp) {\n        need(pp, \"workspace.read\");\n        if (!writer(pp))\n            throw forbidden(\"read_only\", \"Viewers can look but not change anything.\");\n    }\n    const openCount = (ws) => get(\"SELECT COUNT(*) AS n FROM v2_asks WHERE ws_id = ? AND state IN ('open','accepted')\", ws)?.n ?? 0;\n    const createdLastHour = (ws) => get(\"SELECT COUNT(*) AS n FROM v2_asks WHERE ws_id = ? AND created_at > ?\", ws, new (readDate())(readDate().now() - 3600000).toISOString())?.n ?? 0;\n    /** Inside a tx: refuse `adding` more asks when the workspace is at its caps (409 too_many_asks, 429 rate_limited). */\n    function checkCaps(ws, adding) {\n        if (openCount(ws) + adding > OPEN_ASKS_MAX)\n            throw conflict(\"too_many_asks\", `A workspace can have at most ${OPEN_ASKS_MAX} open or accepted asks; close some first.`);\n        if (createdLastHour(ws) + adding > ASKS_PER_HOUR)\n            throw new V2Error(429, \"rate_limited\", \"Too many asks were recorded in the last hour; try again later.\");\n    }\n    function insertAsk(pp, f, state, at) {\n        const id = newId(\"ask\");\n        const decided = state === \"open\" ? null : pp.userId;\n        run(`INSERT INTO v2_asks (id, ws_id, team_id, goal_id, text, from_label, created_by, source_kind, source_title, source_date, state, decided_by, decided_at, created_at, updated_at)\n     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`, id, pp.wsId, f.teamId, f.goalId, f.text, f.fromLabel, pp.userId, f.source.kind, f.source.title, f.source.date, state, decided, decided ? at : null, at, at);\n        return id;\n    }\n    function addMention(pp, a, m, at) {\n        const n = (get(\"SELECT MAX(n) AS n FROM v2_ask_mentions WHERE ask_id = ?\", a.id)?.n ?? 0) + 1;\n        if (n > MENTIONS_MAX)\n            throw conflict(\"too_many_mentions\", `An ask keeps at most ${MENTIONS_MAX} mentions, so this one isn't recorded.`);\n        run(\"INSERT INTO v2_ask_mentions (ws_id, ask_id, n, date, text, source_title, added_by, added_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)\", a.ws_id, a.id, n, m.date, m.text, m.source_title, pp.userId, at);\n        run(\"UPDATE v2_asks SET updated_at = ? WHERE id = ?\", at, a.id);\n    }\n    /** POST .../asks: an owner or member records what a team was asked. */\n    async function createAsk(pp, b) {\n        requireWriter(pp);\n        const f = askIn(pp, b);\n        const at = nowIso();\n        const id = await tx(() => {\n            checkCaps(pp.wsId, 1);\n            const id = insertAsk(pp, f, \"open\", at);\n            audit(pp.wsId, pp.userId, \"ask.created\", id, at);\n            event(\"first_ask\", { ws: pp.wsId, user: pp.userId, at });\n            return id;\n        });\n        return getAsk(pp, id);\n    }\n    /** Text compared for the import merge: case and runs of spaces ignored. */\n    const norm = (t) => t.toLowerCase().replace(/\\s+/g, \" \").trim();\n    const IMPORT_STATES = [\"open\", \"accepted\", \"done\", \"declined\"];\n    /** POST .../asks/import {asks:[…]}: a workspace owner imports up to 60 asks (all valid or none stored). Each item is\n     *  an ask (team_id, text, from_label, goal_id, source) with an optional state (open, accepted, done, declined: the\n     *  importer records it) and up to 10 earlier mentions. It appends and merges, never replaces: an item whose team, text\n     *  and source date match an existing ask changes nothing; one whose team and text match an open or accepted ask with\n     *  another date adds a mention to it (\"came up again\"); anything else is created. */\n    async function importAsks(pp, b) {\n        need(pp, \"workspace.manage\");\n        take(`ask-import:${pp.wsId}`, 10, 60000);\n        if (!Array.isArray(b.asks))\n            throw badRequest(\"Send {asks: [...]}\");\n        if (b.asks.length > IMPORT_MAX)\n            throw badRequest(`asks: at most ${IMPORT_MAX} per import`);\n        const items = b.asks.map((raw, i) => {\n            const p = `asks[${i}].`;\n            const it = obj(raw, `asks[${i}]`);\n            const state = it.state === undefined || it.state === null ? \"open\" : it.state;\n            if (!IMPORT_STATES.includes(state))\n                throw badRequest(`${p}state must be open, accepted, done or declined`);\n            const ms = it.mentions ?? [];\n            if (!Array.isArray(ms))\n                throw badRequest(`${p}mentions must be a list`);\n            if (ms.length > MENTIONS_MAX)\n                throw badRequest(`${p}mentions: at most ${MENTIONS_MAX}`);\n            return { ask: askIn(pp, it, p), state, mentions: ms.map((m, j) => mentionIn(obj(m, `${p}mentions[${j}]`), `${p}mentions[${j}].`)) };\n        });\n        const at = nowIso();\n        return tx(() => {\n            let created = 0;\n            let merged = 0;\n            let unchanged = 0;\n            for (const it of items) {\n                const same = all(\"SELECT * FROM v2_asks WHERE ws_id = ? AND team_id = ?\", pp.wsId, it.ask.teamId).filter((a) => norm(a.text) === norm(it.ask.text));\n                if (same.some((a) => a.source_date === it.ask.source.date)) {\n                    unchanged++;\n                    continue;\n                }\n                const live = same.find((a) => a.state === \"open\" || a.state === \"accepted\");\n                if (live) {\n                    const title = it.ask.source.title ?? \"Recorded by hand\";\n                    const ms = mentionsOf(live.id);\n                    if (ms.length >= MENTIONS_MAX || ms.some((m) => m.date === it.ask.source.date && m.source_title === title))\n                        unchanged++;\n                    else {\n                        addMention(pp, live, { date: it.ask.source.date, text: it.ask.text, source_title: title }, at);\n                        merged++;\n                    }\n                    continue;\n                }\n                const id = insertAsk(pp, it.ask, it.state, at);\n                const a = askRow(pp.wsId, id);\n                for (const m of it.mentions)\n                    addMention(pp, a, m, at);\n                created++;\n            }\n            checkCaps(pp.wsId, 0);\n            if (createdLastHour(pp.wsId) > ASKS_PER_HOUR)\n                throw new V2Error(429, \"rate_limited\", \"Too many asks were recorded in the last hour; try again later.\");\n            audit(pp.wsId, pp.userId, \"ask.imported\", String(created + merged), at);\n            if (created)\n                event(\"first_ask\", { ws: pp.wsId, user: pp.userId, at });\n            return { created, merged, unchanged };\n        });\n    }\n    const AUDIT = {\n        accept: \"ask.accepted\",\n        decline: \"ask.declined\",\n        done: \"ask.done\",\n        reopen: \"ask.reopened\",\n        withdraw: \"ask.withdrawn\",\n        mention: \"ask.mentioned\",\n    };\n    const NEXT = { accept: \"accepted\", decline: \"declined\", done: \"done\", reopen: \"open\", withdraw: \"withdrawn\" };\n    const FROM = {\n        accept: [\"open\"],\n        decline: [\"open\"],\n        done: [\"accepted\"],\n        reopen: [\"done\", \"declined\"],\n        withdraw: [\"open\", \"accepted\"],\n        mention: [\"open\", \"accepted\"],\n    };\n    /** Why an action on an ask in another state is refused (409 wrong_state), in the words change requests use (c9 W4):\n     *  what happened, who did it (\"you\" to the reader), and a full stop, never \"This ask is <state>\". */\n    function askStateRefusal(a, reader) {\n        const who = a.decided_by;\n        const self = who === reader;\n        const by = who ? ` by ${memberName(who)}` : \"\";\n        switch (a.state) {\n            case \"open\":\n                return who ? `${self ? \"You\" : memberName(who)} reopened this ask, so it waits for the team asked to accept it again.` : \"This ask waits for the team asked to accept it.\";\n            case \"accepted\":\n                return self ? \"You already accepted this ask.\" : `This ask was already accepted${by}.`;\n            case \"done\":\n                return self ? \"You marked this ask done.\" : `This ask was marked done${by}.`;\n            case \"declined\":\n                return self ? \"You declined this ask, so nothing changes.\" : `This ask was declined${by}, so nothing changes.`;\n            case \"withdrawn\":\n                return a.created_by === reader ? \"You withdrew this ask, so nothing changes.\" : `This ask was withdrawn by ${memberName(a.created_by)}, so nothing changes.`;\n        }\n    }\n    /** POST .../asks/{id}/{action}. Unreadable: 404. Viewers: 403 read_only. Then who: accept, decline and reopen need a\n     *  lead of the team asked or a workspace owner (403 not_team_lead); done any member of the team or a workspace owner\n     *  (403 not_in_team); withdraw the person who recorded it (403 not_requester). Then the state (409 wrong_state). */\n    async function actOnAsk(pp, id, action, b) {\n        visibleAsk(pp, id);\n        requireWriter(pp);\n        take(`ask-action:${pp.userId}`, ASK_ACTIONS_PER_MINUTE, 60000);\n        const mention = action === \"mention\" ? mentionIn(b) : null;\n        const at = nowIso();\n        await tx(() => {\n            const a = askRow(pp.wsId, id); // re-read inside the transaction\n            if ((action === \"accept\" || action === \"decline\" || action === \"reopen\") && !leads(pp, a) && !isOwner(pp))\n                throw forbidden(\"not_team_lead\", \"Only a lead of the team asked, or a workspace owner, can do this.\");\n            if (action === \"done\" && !inTeam(pp, a) && !isOwner(pp))\n                throw forbidden(\"not_in_team\", \"Only the team asked, or a workspace owner, can mark it done.\");\n            if (action === \"withdraw\" && a.created_by !== pp.userId)\n                throw forbidden(\"not_requester\", \"Only the person who recorded this ask can withdraw it.\");\n            if (!FROM[action].includes(a.state))\n                throw conflict(\"wrong_state\", askStateRefusal(a, pp.userId));\n            if (mention)\n                addMention(pp, a, mention, at);\n            else\n                run(\"UPDATE v2_asks SET state = ?, decided_by = ?, decided_at = ?, updated_at = ? WHERE id = ?\", NEXT[action], pp.userId, at, at, a.id);\n            audit(pp.wsId, pp.userId, AUDIT[action], a.id, at);\n        });\n        return getAsk(pp, id);\n    }\n    function assertAskAction(a) {\n        if (!ASK_ACTIONS.includes(a))\n            throw notFound();\n        return a;\n    }\n    return { ASK_STATES, ASK_ACTIONS, ASK_TEXT_MAX, ASK_FROM_MAX, ASK_TITLE_MAX, MENTION_TEXT_MAX,